import React from "react";
import "./Communication.css"; // Import CSS

function CommunicationCard() {
  return (
    <div className="emotional-card">
      {/* Paw Icon at the top left */}
      <img src="/Paw.png" alt="Paw Icon" className="paw-icon" />

      {/* Title */}
      <h3 className="card-title">Communication</h3>

      {/* Description */}
      <p className="card-text">
      Animals can communicate better with people in such conditions, as verbal communication is replaced by non-verbal
      </p>

      {/* Cat Icon at the bottom left */}
      <img src="/Dog1.png" alt="Cat Icon" className="dog-icon" />
    </div>
  );
}

export default CommunicationCard;
